// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    address deployer;

    function setUp() public {
        c = new RoundFactory();
        deployer = address(this);
        c.initialize();
    }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != address(this));
        vm.prank(address(this));
        try c.transferOwnership(newOwner) {
            assertTrue(c.owner() == newOwner, "owner must be set to newOwner");
        } catch {
            assertTrue(false, "transferOwnership must succeed for the owner");
        }
    }
}
